use leptos::prelude::*;
use leptos_meta::Title;

// The curated entries below are the narrative layer. The complete record is
// rendered from the ORCID snapshot baked in at build time (src/orcid_data.rs,
// regenerated by scripts/fetch-orcid.py) and refreshed in the browser from the
// ORCID public API by /js/orcid.js — the list the visitor sees is live.
#[component]
pub fn Research() -> impl IntoView {
    view! {
        <Title text="Research - Qompass AI" />
        <section class="page">
            <p class="page-bearing">"CHART — PUBLICATIONS & PREPRINTS"</p>
            <h1>"Research"</h1>
            <p class="page-lede">
                "Peer-reviewed work, preprints, and benchmark studies. The complete record "
                "below is drawn live from "
                <a href="https://orcid.org/0000-0002-0302-4812">"ORCID 0000-0002-0302-4812"</a>
                " — when the ORCID record changes, this page follows."
            </p>
            <div class="entry-list">
                <article class="entry">
                    <p class="entry-kind">"BENCHMARK STUDY"</p>
                    <h2>"Post-quantum KEM benchmarking (qompassai/KO)"</h2>
                    <p>
                        "24 NIST post-quantum key-encapsulation mechanisms benchmarked head to "
                        "head — timings, memory, and failure behavior, measured rather than "
                        "quoted from spec sheets. Submitted to the 2025 AMA Research Challenge."
                    </p>
                </article>
                <article class="entry">
                    <p class="entry-kind">"POSITION PAPER"</p>
                    <h2>"First, Do No Harm"</h2>
                    <p>
                        "A pragmatic standard for safe, secure, and trustworthy AI: drawn from "
                        "clinical medicine's oldest rule and a red teamer's threat model, and "
                        "written to be applied, not admired."
                    </p>
                </article>
                <article class="entry">
                    <p class="entry-kind">
                        "PEER-REVIEWED LETTER — CLINICAL ORTHOPAEDICS AND RELATED RESEARCH (2024)"
                    </p>
                    <h2>"Generative AI and value-based healthcare"</h2>
                    <p>
                        "On what generative AI actually changes in value-based care — where it "
                        "earns its cost, where it does not, and the evidence bar it should be "
                        "held to before it touches a patient."
                    </p>
                </article>
                <article class="entry">
                    <p class="entry-kind">"PEER REVIEW"</p>
                    <h2>"Reviewer — JGME, JMIR, and orthopaedic journals"</h2>
                    <p>
                        "Ongoing peer review of manuscripts on LLMs in medical education and "
                        "clinical AI — the same evidence standard, applied to other people's "
                        "claims."
                    </p>
                </article>
            </div>
            <h2 class="record-head">"On the Chart — Research in Progress"</h2>
            <p class="record-meta">
                "The working log, published as it goes. Only entries flagged public appear "
                "here; abstracts appear only when flagged ready for daylight."
            </p>
            <div class="entry-list">
                {crate::tracker_data::TRACKER
                    .iter()
                    .map(|t| {
                        let stage_label = match t.stage {
                            "soundings" => "STAGE — SOUNDINGS",
                            "drafting" => "STAGE — DRAFTING",
                            "in-review" => "STAGE — IN REVIEW",
                            "ready" => "STAGE — READY TO PUBLISH",
                            "published" => "STAGE — PUBLISHED",
                            _ => "STAGE — ANCHORED",
                        };
                        view! {
                            <article class="entry tracker-entry">
                                <p class="entry-kind">
                                    {stage_label} " · UPDATED " {t.updated}
                                </p>
                                <h2>{t.title}</h2>
                                <p>{t.topic}</p>
                                {(!t.abstract_text.is_empty())
                                    .then(|| {
                                        view! {
                                            <p class="tracker-abstract">{t.abstract_text}</p>
                                        }
                                    })}
                                {(!t.next_step.is_empty())
                                    .then(|| {
                                        view! {
                                            <p class="tracker-next">
                                                <span class="tracker-next-label">"Next: "</span>
                                                {t.next_step}
                                            </p>
                                        }
                                    })}
                            </article>
                        }
                    })
                    .collect_view()}
            </div>
            <h2 class="record-head">"Complete record — live from ORCID"</h2>
            <p class="record-meta">
                <span id="orcid-status">"Snapshot from build time; refreshing from ORCID…"</span>
            </p>
            <ul class="record-list" id="orcid-works">
                {crate::orcid_data::WORKS
                    .iter()
                    .map(|w| {
                        view! {
                            <li class="record-item">
                                <span class="record-year">{w.year}</span>
                                <span class="record-title">
                                    <a href={w.url}>{w.title}</a>
                                </span>
                                <span class="record-venue">{w.venue}</span>
                            </li>
                        }
                    })
                    .collect_view()}
            </ul>
        </section>
        <script type="module" src="/js/orcid.js"></script>
    }
}
